	addRule(&models.Rule{ID: "rule:aliyun:ecs-instance-chargetype-check", Name: models.I18nString{"de": "ECS-Instanz-Gebührentyp-Prüfung", "en": "ECS Instance Charge Type Check", "es": "Verificación de Tipo de Cargo de Instancia ECS", "fr": "Vérification du Type de Facturation de l'Instance ECS", "ja": "ECS インスタンスの課金タイプチェック", "pt": "Verificação de Tipo de Cobrança da Instância ECS", "zh": "ECS 实例付费类型核查"}, Severity: "low", Description: models.I18nString{"de": "Stellt sicher, dass ECS-Instanzen den autorisierten Gebührentyp verwenden.", "en": "Ensures ECS instances use the authorized charge type.", "es": "Garantiza que las instancias ECS usen el tipo de cargo autorizado.", "fr": "Garantit que les instances ECS utilisent le type de facturation autorisé.", "ja": "ECS インスタンスが承認された課金タイプを使用していることを確認します。", "pt": "Garante que as instâncias ECS usem o tipo de cobrança autorizado.", "zh": "确保 ECS 实例使用授权的付费类型。"}, Reason: models.I18nString{"de": "Die Durchsetzung spezifischer Gebührentypen (z. B. PostPaid) entspricht den organisatorischen Budgetrichtlinien.", "en": "Enforcing specific charge types (e.g., PostPaid) aligns with organizational budget policies.", "es": "Hacer cumplir tipos de cargo específicos (por ejemplo, PostPaid) se alinea con las políticas presupuestarias organizacionales.", "fr": "L'application de types de facturation spécifiques (par exemple, PostPaid) s'aligne sur les politiques budgétaires organisationnelles.", "ja": "特定の課金タイプ（例：PostPaid）を強制することは、組織の予算ポリシーと一致します。", "pt": "Aplicar tipos de cobrança específicos (por exemplo, PostPaid) está alinhado com as políticas orçamentárias organizacionais.", "zh": "强制执行特定的付费类型（如后付费）符合组织预算政策。"}, Recommendation: models.I18nString{"de": "Setzen Sie InstanceChargeType auf 'PostPaid'.", "en": "Set InstanceChargeType to 'PostPaid'.", "es": "Establezca InstanceChargeType en 'PostPaid'.", "fr": "Définissez InstanceChargeType sur 'PostPaid'.", "ja": "InstanceChargeType を 'PostPaid' に設定します。", "pt": "Defina InstanceChargeType como 'PostPaid'.", "zh": "将 InstanceChargeType 设置为'PostPaid'。"}, ResourceTypes: []string{"ALIYUN::ECS::Instance", "ALIYUN::ECS::InstanceGroup"}, IaCTypes: []string{"ros"}, Implementations: map[string]*models.RuleImpl(nil), FilePath: "aliyun/rules/ros/ecs-instance-chargetype-check.rego", PackageName: "infraguard.rules.aliyun.ecs_instance_chargetype_check", Content: "package infraguard.rules.aliyun.ecs_instance_chargetype_check\n\nimport data.infraguard.helpers\nimport rego.v1\n\nrule_meta := {\n\t\"id\": \"ecs-instance-chargetype-check\",\n\t\"severity\": \"low\",\n\t\"name\": {\n\t\t\"en\": \"ECS Instance Charge Type Check\",\n\t\t\"zh\": \"ECS 实例付费类型核查\",\n\t\t\"ja\": \"ECS インスタンスの課金タイプチェック\",\n\t\t\"de\": \"ECS-Instanz-Gebührentyp-Prüfung\",\n\t\t\"es\": \"Verificación de Tipo de Cargo de Instancia ECS\",\n\t\t\"fr\": \"Vérification du Type de Facturation de l'Instance ECS\",\n\t\t\"pt\": \"Verificação de Tipo de Cobrança da Instância ECS\"\n\t},\n\t\"description\": {\n\t\t\"en\": \"Ensures ECS instances use the authorized charge type.\",\n\t\t\"zh\": \"确保 ECS 实例使用授权的付费类型。\",\n\t\t\"ja\": \"ECS インスタンスが承認された課金タイプを使用していることを確認します。\",\n\t\t\"de\": \"Stellt sicher, dass ECS-Instanzen den autorisierten Gebührentyp verwenden.\",\n\t\t\"es\": \"Garantiza que las instancias ECS usen el tipo de cargo autorizado.\",\n\t\t\"fr\": \"Garantit que les instances ECS utilisent le type de facturation autorisé.\",\n\t\t\"pt\": \"Garante que as instâncias ECS usem o tipo de cobrança autorizado.\"\n\t},\n\t\"reason\": {\n\t\t\"en\": \"Enforcing specific charge types (e.g., PostPaid) aligns with organizational budget policies.\",\n\t\t\"zh\": \"强制执行特定的付费类型（如后付费）符合组织预算政策。\",\n\t\t\"ja\": \"特定の課金タイプ（例：PostPaid）を強制することは、組織の予算ポリシーと一致します。\",\n\t\t\"de\": \"Die Durchsetzung spezifischer Gebührentypen (z. B. PostPaid) entspricht den organisatorischen Budgetrichtlinien.\",\n\t\t\"es\": \"Hacer cumplir tipos de cargo específicos (por ejemplo, PostPaid) se alinea con las políticas presupuestarias organizacionales.\",\n\t\t\"fr\": \"L'application de types de facturation spécifiques (par exemple, PostPaid) s'aligne sur les politiques budgétaires organisationnelles.\",\n\t\t\"pt\": \"Aplicar tipos de cobrança específicos (por exemplo, PostPaid) está alinhado com as políticas orçamentárias organizacionais.\"\n\t},\n\t\"recommendation\": {\n\t\t\"en\": \"Set InstanceChargeType to 'PostPaid'.\",\n\t\t\"zh\": \"将 InstanceChargeType 设置为'PostPaid'。\",\n\t\t\"ja\": \"InstanceChargeType を 'PostPaid' に設定します。\",\n\t\t\"de\": \"Setzen Sie InstanceChargeType auf 'PostPaid'.\",\n\t\t\"es\": \"Establezca InstanceChargeType en 'PostPaid'.\",\n\t\t\"fr\": \"Définissez InstanceChargeType sur 'PostPaid'.\",\n\t\t\"pt\": \"Defina InstanceChargeType como 'PostPaid'.\"\n\t},\n\t\"resource_types\": [\"ALIYUN::ECS::Instance\", \"ALIYUN::ECS::InstanceGroup\"]\n}\n\nis_compliant(resource) if {\n\tcharge_type := helpers.get_property(resource, \"InstanceChargeType\", \"PostPaid\")\n\tcharge_type == \"PostPaid\"\n}\n\ndeny contains result if {\n\tsome name, resource in helpers.resources_by_types(rule_meta.resource_types)\n\tnot is_compliant(resource)\n\tresult := {\n\t\t\"id\": rule_meta.id,\n\t\t\"resource_id\": name,\n\t\t\"violation_path\": [\"Properties\", \"InstanceChargeType\"],\n\t\t\"meta\": {\"severity\": rule_meta.severity, \"reason\": rule_meta.reason, \"recommendation\": rule_meta.recommendation},\n\t}\n}\n"})
	addRule(&models.Rule{ID: "rule:aliyun:ecs-instance-chargetype-check", Name: models.I18nString{"de": "ECS-Instanz-Gebührentyp-Prüfung", "en": "ECS Instance Charge Type Check", "es": "Verificación de Tipo de Cargo de Instancia ECS", "fr": "Vérification du Type de Facturation de l'Instance ECS", "ja": "ECS インスタンスの課金タイプチェック", "pt": "Verificação de Tipo de Cobrança da Instância ECS", "zh": "ECS 实例付费类型核查"}, Severity: "low", Description: models.I18nString{"de": "Stellt sicher, dass ECS-Instanzen den autorisierten Gebührentyp verwenden.", "en": "Ensures ECS instances use the authorized charge type.", "es": "Garantiza que las instancias ECS usen el tipo de cargo autorizado.", "fr": "Garantit que les instances ECS utilisent le type de facturation autorisé.", "ja": "ECS インスタンスが承認された課金タイプを使用していることを確認します。", "pt": "Garante que as instâncias ECS usem o tipo de cobrança autorizado.", "zh": "确保 ECS 实例使用授权的付费类型。"}, Reason: models.I18nString{"de": "Die Durchsetzung spezifischer Gebührentypen (z. B. PostPaid) entspricht den organisatorischen Budgetrichtlinien.", "en": "Enforcing specific charge types (e.g., PostPaid) aligns with organizational budget policies.", "es": "Hacer cumplir tipos de cargo específicos (por ejemplo, PostPaid) se alinea con las políticas presupuestarias organizacionales.", "fr": "L'application de types de facturation spécifiques (par exemple, PostPaid) s'aligne sur les politiques budgétaires organisationnelles.", "ja": "特定の課金タイプ（例：PostPaid）を強制することは、組織の予算ポリシーと一致します。", "pt": "Aplicar tipos de cobrança específicos (por exemplo, PostPaid) está alinhado com as políticas orçamentárias organizacionais.", "zh": "强制执行特定的付费类型（如后付费）符合组织预算政策。"}, Recommendation: models.I18nString{"de": "Setzen Sie InstanceChargeType auf 'PostPaid'.", "en": "Set InstanceChargeType to 'PostPaid'.", "es": "Establezca InstanceChargeType en 'PostPaid'.", "fr": "Définissez InstanceChargeType sur 'PostPaid'.", "ja": "InstanceChargeType を 'PostPaid' に設定します。", "pt": "Defina InstanceChargeType como 'PostPaid'.", "zh": "将 InstanceChargeType 设置为'PostPaid'。"}, ResourceTypes: []string{"alicloud_instance"}, IaCTypes: []string{"terraform"}, Implementations: map[string]*models.RuleImpl(nil), FilePath: "aliyun/rules/terraform/ecs-instance-chargetype-check.rego", PackageName: "infraguard.rules.terraform.ecs_instance_chargetype_check", Content: "package infraguard.rules.terraform.ecs_instance_chargetype_check\n\nimport rego.v1\n\nimport data.infraguard.helpers.terraform as tf\n\nrule_meta := {\n\t\"id\": \"ecs-instance-chargetype-check\",\n\t\"severity\": \"low\",\n\t\"name\": {\n\t\t\"en\": \"ECS Instance Charge Type Check\",\n\t\t\"zh\": \"ECS 实例付费类型核查\",\n\t\t\"ja\": \"ECS インスタンスの課金タイプチェック\",\n\t\t\"de\": \"ECS-Instanz-Gebührentyp-Prüfung\",\n\t\t\"es\": \"Verificación de Tipo de Cargo de Instancia ECS\",\n\t\t\"fr\": \"Vérification du Type de Facturation de l'Instance ECS\",\n\t\t\"pt\": \"Verificação de Tipo de Cobrança da Instância ECS\"\n\t},\n\t\"description\": {\n\t\t\"en\": \"Ensures ECS instances use the authorized charge type.\",\n\t\t\"zh\": \"确保 ECS 实例使用授权的付费类型。\",\n\t\t\"ja\": \"ECS インスタンスが承認された課金タイプを使用していることを確認します。\",\n\t\t\"de\": \"Stellt sicher, dass ECS-Instanzen den autorisierten Gebührentyp verwenden.\",\n\t\t\"es\": \"Garantiza que las instancias ECS usen el tipo de cargo autorizado.\",\n\t\t\"fr\": \"Garantit que les instances ECS utilisent le type de facturation autorisé.\",\n\t\t\"pt\": \"Garante que as instâncias ECS usem o tipo de cobrança autorizado.\"\n\t},\n\t\"reason\": {\n\t\t\"en\": \"Enforcing specific charge types (e.g., PostPaid) aligns with organizational budget policies.\",\n\t\t\"zh\": \"强制执行特定的付费类型（如后付费）符合组织预算政策。\",\n\t\t\"ja\": \"特定の課金タイプ（例：PostPaid）を強制することは、組織の予算ポリシーと一致します。\",\n\t\t\"de\": \"Die Durchsetzung spezifischer Gebührentypen (z. B. PostPaid) entspricht den organisatorischen Budgetrichtlinien.\",\n\t\t\"es\": \"Hacer cumplir tipos de cargo específicos (por ejemplo, PostPaid) se alinea con las políticas presupuestarias organizacionales.\",\n\t\t\"fr\": \"L'application de types de facturation spécifiques (par exemple, PostPaid) s'aligne sur les politiques budgétaires organisationnelles.\",\n\t\t\"pt\": \"Aplicar tipos de cobrança específicos (por exemplo, PostPaid) está alinhado com as políticas orçamentárias organizacionais.\"\n\t},\n\t\"recommendation\": {\n\t\t\"en\": \"Set InstanceChargeType to 'PostPaid'.\",\n\t\t\"zh\": \"将 InstanceChargeType 设置为'PostPaid'。\",\n\t\t\"ja\": \"InstanceChargeType を 'PostPaid' に設定します。\",\n\t\t\"de\": \"Setzen Sie InstanceChargeType auf 'PostPaid'.\",\n\t\t\"es\": \"Establezca InstanceChargeType en 'PostPaid'.\",\n\t\t\"fr\": \"Définissez InstanceChargeType sur 'PostPaid'.\",\n\t\t\"pt\": \"Defina InstanceChargeType como 'PostPaid'.\"\n\t},\n\t\"resource_types\": [\"alicloud_instance\"],\n\t\"iac_type\": \"terraform\"\n}\n\nviolation_for(name) := {\n\t\"id\": rule_meta.id,\n\t\"resource_id\": sprintf(\"alicloud_instance.%s\", [name]),\n\t\"meta\": {\n\t\t\"severity\": rule_meta.severity,\n\t\t\"reason\": rule_meta.reason,\n\t\t\"recommendation\": rule_meta.recommendation,\n\t},\n}\n\ndeny contains violation if {\n\tsome name, resource in tf.resources_by_type(\"alicloud_instance\")\n\tcharge_type := tf.get_attribute(resource, \"instance_charge_type\", \"PostPaid\")\n\tnot tf.is_unknown(charge_type)\n\tcharge_type != \"PostPaid\"\n\tviolation := violation_for(name)\n}\n"})
	addRule(&models.Rule{ID: "rule:aliyun:ecs-instance-deletion-protection-enabled", Name: models.I18nString{"de": "ECS-Instanz Löschschutz aktiviert", "en": "ECS Instance Deletion Protection Enabled", "es": "Protección de Eliminación de Instancia ECS Habilitada", "fr": "Protection contre la Suppression d'Instance ECS Activée", "ja": "ECS インスタンスの削除保護が有効", "pt": "Proteção contra Exclusão de Instância ECS Habilitada", "zh": "ECS 实例开启释放保护"}, Severity: "high", Description: models.I18nString{"de": "Stellt sicher, dass ECS-Instanzen Löschschutz aktiviert haben.", "en": "Ensures that ECS instances have deletion protection enabled.", "es": "Asegura que las instancias ECS tengan habilitada la protección contra eliminación.", "fr": "Garantit que les instances ECS ont la protection contre la suppression activée.", "ja": "ECS インスタンスで削除保護が有効になっていることを確認します。", "pt": "Garante que as instâncias ECS tenham proteção contra exclusão habilitada.", "zh": "确保 ECS 实例开启了释放保护。"}, Reason: models.I18nString{"de": "Wenn der Löschschutz nicht aktiviert ist, kann die Instanz versehentlich freigegeben werden, was zu Dienstunterbrechungen oder Datenverlust führt.", "en": "If deletion protection is not enabled, the instance may be released accidentally, causing service interruption or data loss.", "es": "Si la protección contra eliminación no está habilitada, la instancia puede ser liberada accidentalmente, causando interrupción del servicio o pérdida de datos.", "fr": "Si la protection contre la suppression n'est pas activée, l'instance peut être libérée accidentellement, provoquant une interruption de service ou une perte de données.", "ja": "削除保護が有効になっていない場合、インスタンスが誤って解放され、サービス中断やデータ損失が発生する可能性があります。", "pt": "Se a proteção contra exclusão não estiver habilitada, a instância pode ser liberada acidentalmente, causando interrupção do serviço ou perda de dados.", "zh": "如果未开启释放保护，实例可能会被意外释放，导致业务中断或数据丢失。"}, Recommendation: models.I18nString{"de": "Aktivieren Sie den Löschschutz für die ECS-Instanz.", "en": "Enable deletion protection for the ECS instance.", "es": "Habilite la protección contra eliminación para la instancia ECS.", "fr": "Activez la protection contre la suppression pour l'instance ECS.", "ja": "ECS インスタンスで削除保護を有効にします。", "pt": "Habilite proteção contra exclusão para a instância ECS.", "zh": "为 ECS 实例开启释放保护功能。"}, ResourceTypes: []string{"ALIYUN::ECS::Instance", "ALIYUN::ECS::InstanceGroup"}, IaCTypes: []string{"ros"}, Implementations: map[string]*models.RuleImpl(nil), FilePath: "aliyun/rules/ros/ecs-instance-deletion-protection-enabled.rego", PackageName: "infraguard.rules.aliyun.ecs_instance_deletion_protection_enabled", Content: "package infraguard.rules.aliyun.ecs_instance_deletion_protection_enabled\n\nimport rego.v1\n\nimport data.infraguard.helpers\n\nrule_meta := {\n\t\"id\": \"ecs-instance-deletion-protection-enabled\",\n\t\"severity\": \"high\",\n\t\"name\": {\n\t\t\"en\": \"ECS Instance Deletion Protection Enabled\",\n\t\t\"zh\": \"ECS 实例开启释放保护\",\n\t\t\"ja\": \"ECS インスタンスの削除保護が有効\",\n\t\t\"de\": \"ECS-Instanz Löschschutz aktiviert\",\n\t\t\"es\": \"Protección de Eliminación de Instancia ECS Habilitada\",\n\t\t\"fr\": \"Protection contre la Suppression d'Instance ECS Activée\",\n\t\t\"pt\": \"Proteção contra Exclusão de Instância ECS Habilitada\"\n\t},\n\t\"description\": {\n\t\t\"en\": \"Ensures that ECS instances have deletion protection enabled.\",\n\t\t\"zh\": \"确保 ECS 实例开启了释放保护。\",\n\t\t\"ja\": \"ECS インスタンスで削除保護が有効になっていることを確認します。\",\n\t\t\"de\": \"Stellt sicher, dass ECS-Instanzen Löschschutz aktiviert haben.\",\n\t\t\"es\": \"Asegura que las instancias ECS tengan habilitada la protección contra eliminación.\",\n\t\t\"fr\": \"Garantit que les instances ECS ont la protection contre la suppression activée.\",\n\t\t\"pt\": \"Garante que as instâncias ECS tenham proteção contra exclusão habilitada.\"\n\t},\n\t\"reason\": {\n\t\t\"en\": \"If deletion protection is not enabled, the instance may be released accidentally, causing service interruption or data loss.\",\n\t\t\"zh\": \"如果未开启释放保护，实例可能会被意外释放，导致业务中断或数据丢失。\",\n\t\t\"ja\": \"削除保護が有効になっていない場合、インスタンスが誤って解放され、サービス中断やデータ損失が発生する可能性があります。\",\n\t\t\"de\": \"Wenn der Löschschutz nicht aktiviert ist, kann die Instanz versehentlich freigegeben werden, was zu Dienstunterbrechungen oder Datenverlust führt.\",\n\t\t\"es\": \"Si la protección contra eliminación no está habilitada, la instancia puede ser liberada accidentalmente, causando interrupción del servicio o pérdida de datos.\",\n\t\t\"fr\": \"Si la protection contre la suppression n'est pas activée, l'instance peut être libérée accidentellement, provoquant une interruption de service ou une perte de données.\",\n\t\t\"pt\": \"Se a proteção contra exclusão não estiver habilitada, a instância pode ser liberada acidentalmente, causando interrupção do serviço ou perda de dados.\"\n\t},\n\t\"recommendation\": {\n\t\t\"en\": \"Enable deletion protection for the ECS instance.\",\n\t\t\"zh\": \"为 ECS 实例开启释放保护功能。\",\n\t\t\"ja\": \"ECS インスタンスで削除保護を有効にします。\",\n\t\t\"de\": \"Aktivieren Sie den Löschschutz für die ECS-Instanz.\",\n\t\t\"es\": \"Habilite la protección contra eliminación para la instancia ECS.\",\n\t\t\"fr\": \"Activez la protection contre la suppression pour l'instance ECS.\",\n\t\t\"pt\": \"Habilite proteção contra exclusão para a instância ECS.\"\n\t},\n\t\"resource_types\": [\"ALIYUN::ECS::Instance\", \"ALIYUN::ECS::InstanceGroup\"]\n}\n\nis_compliant(resource) if {\n\thelpers.is_true(helpers.get_property(resource, \"DeletionProtection\", false))\n}\n\ndeny contains result if {\n\tsome name, resource in helpers.resources_by_types([\"ALIYUN::ECS::Instance\", \"ALIYUN::ECS::InstanceGroup\"])\n\tnot is_compliant(resource)\n\tresult := {\n\t\t\"id\": rule_meta.id,\n\t\t\"resource_id\": name,\n\t\t\"violation_path\": [\"Properties\", \"DeletionProtection\"],\n\t\t\"meta\": {\n\t\t\t\"severity\": rule_meta.severity,\n\t\t\t\"reason\": rule_meta.reason,\n\t\t\t\"recommendation\": rule_meta.recommendation,\n\t\t},\n\t}\n}\n"})
