	addRule(&models.Rule{ID: "rule:aliyun:polardb-cluster-expired-check", Name: models.I18nString{"de": "PolarDB-Cluster Ablaufprüfung", "en": "PolarDB Cluster Expiration Check", "es": "Verificación de Expiración de Cluster PolarDB", "fr": "Vérification d'Expiration du Cluster PolarDB", "ja": "PolarDB クラスタの有効期限チェック", "pt": "Verificação de Expiração de Cluster PolarDB", "zh": "PolarDB 集群到期检查"}, Severity: "high", Description: models.I18nString{"de": "Vorausbezahlte PolarDB-Cluster sollten automatische Verlängerung aktiviert haben.", "en": "Prepaid PolarDB clusters should have auto-renewal enabled.", "es": "Los clústeres PolarDB prepagos deben tener renovación automática habilitada.", "fr": "Les clusters PolarDB prépayés doivent avoir le renouvellement automatique activé.", "ja": "プリペイド PolarDB クラスタは自動更新を有効にする必要があります。", "pt": "Clusters PolarDB pré-pagos devem ter renovação automática habilitada.", "zh": "预付费 PolarDB 集群应开启自动续费，避免业务中断。"}, Reason: models.I18nString{"de": "Der vorausbezahlte PolarDB-Cluster hat keine automatische Verlängerung aktiviert.", "en": "The prepaid PolarDB cluster does not have auto-renewal enabled.", "es": "El clúster PolarDB prepago no tiene renovación automática habilitada.", "fr": "Le cluster PolarDB prépayé n'a pas le renouvellement automatique activé.", "ja": "プリペイド PolarDB クラスタで自動更新が有効になっていません。", "pt": "O cluster PolarDB pré-pago não tem renovação automática habilitada.", "zh": "预付费 PolarDB 集群未开启自动续费。"}, Recommendation: models.I18nString{"de": "Setzen Sie renewal_status für den vorausbezahlten PolarDB-Cluster auf AutoRenewal.", "en": "Set renewal_status to AutoRenewal for the prepaid PolarDB cluster.", "es": "Establezca renewal_status en AutoRenewal para el clúster PolarDB prepago.", "fr": "Définissez renewal_status sur AutoRenewal pour le cluster PolarDB prépayé.", "ja": "プリペイド PolarDB クラスタの renewal_status を AutoRenewal に設定します。", "pt": "Defina renewal_status como AutoRenewal para o cluster PolarDB pré-pago.", "zh": "为预付费 PolarDB 集群将 renewal_status 设置为 AutoRenewal。"}, ResourceTypes: []string{"alicloud_polardb_cluster"}, IaCTypes: []string{"terraform"}, Implementations: map[string]*models.RuleImpl(nil), FilePath: "aliyun/rules/terraform/polardb-cluster-expired-check.rego", PackageName: "infraguard.rules.terraform.polardb_cluster_expired_check", Content: "package infraguard.rules.terraform.polardb_cluster_expired_check\n\nimport rego.v1\n\nimport data.infraguard.helpers.terraform as tf\n\nrule_meta := {\n\t\"id\": \"polardb-cluster-expired-check\",\n\t\"severity\": \"high\",\n\t\"name\": {\n\t\t\"en\": \"PolarDB Cluster Expiration Check\",\n\t\t\"zh\": \"PolarDB 集群到期检查\",\n\t\t\"ja\": \"PolarDB クラスタの有効期限チェック\",\n\t\t\"de\": \"PolarDB-Cluster Ablaufprüfung\",\n\t\t\"es\": \"Verificación de Expiración de Cluster PolarDB\",\n\t\t\"fr\": \"Vérification d'Expiration du Cluster PolarDB\",\n\t\t\"pt\": \"Verificação de Expiração de Cluster PolarDB\"\n\t},\n\t\"description\": {\n\t\t\"en\": \"Prepaid PolarDB clusters should have auto-renewal enabled.\",\n\t\t\"zh\": \"预付费 PolarDB 集群应开启自动续费，避免业务中断。\",\n\t\t\"ja\": \"プリペイド PolarDB クラスタは自動更新を有効にする必要があります。\",\n\t\t\"de\": \"Vorausbezahlte PolarDB-Cluster sollten automatische Verlängerung aktiviert haben.\",\n\t\t\"es\": \"Los clústeres PolarDB prepagos deben tener renovación automática habilitada.\",\n\t\t\"fr\": \"Les clusters PolarDB prépayés doivent avoir le renouvellement automatique activé.\",\n\t\t\"pt\": \"Clusters PolarDB pré-pagos devem ter renovação automática habilitada.\"\n\t},\n\t\"reason\": {\n\t\t\"en\": \"The prepaid PolarDB cluster does not have auto-renewal enabled.\",\n\t\t\"zh\": \"预付费 PolarDB 集群未开启自动续费。\",\n\t\t\"ja\": \"プリペイド PolarDB クラスタで自動更新が有効になっていません。\",\n\t\t\"de\": \"Der vorausbezahlte PolarDB-Cluster hat keine automatische Verlängerung aktiviert.\",\n\t\t\"es\": \"El clúster PolarDB prepago no tiene renovación automática habilitada.\",\n\t\t\"fr\": \"Le cluster PolarDB prépayé n'a pas le renouvellement automatique activé.\",\n\t\t\"pt\": \"O cluster PolarDB pré-pago não tem renovação automática habilitada.\"\n\t},\n\t\"recommendation\": {\n\t\t\"en\": \"Set renewal_status to AutoRenewal for the prepaid PolarDB cluster.\",\n\t\t\"zh\": \"为预付费 PolarDB 集群将 renewal_status 设置为 AutoRenewal。\",\n\t\t\"ja\": \"プリペイド PolarDB クラスタの renewal_status を AutoRenewal に設定します。\",\n\t\t\"de\": \"Setzen Sie renewal_status für den vorausbezahlten PolarDB-Cluster auf AutoRenewal.\",\n\t\t\"es\": \"Establezca renewal_status en AutoRenewal para el clúster PolarDB prepago.\",\n\t\t\"fr\": \"Définissez renewal_status sur AutoRenewal pour le cluster PolarDB prépayé.\",\n\t\t\"pt\": \"Defina renewal_status como AutoRenewal para o cluster PolarDB pré-pago.\"\n\t},\n\t\"resource_types\": [\"alicloud_polardb_cluster\"],\n\t\"iac_type\": \"terraform\"\n}\n\ndeny contains violation if {\n\tsome name, resource in tf.resources_by_type(\"alicloud_polardb_cluster\")\n\ttf.get_attribute(resource, \"pay_type\", \"PostPaid\") == \"PrePaid\"\n\ttf.get_attribute(resource, \"renewal_status\", \"Normal\") != \"AutoRenewal\"\n\tviolation := {\n\t\t\"id\": rule_meta.id,\n\t\t\"resource_id\": sprintf(\"alicloud_polardb_cluster.%s\", [name]),\n\t\t\"meta\": {\"severity\": rule_meta.severity, \"reason\": rule_meta.reason, \"recommendation\": rule_meta.recommendation},\n\t}\n}\n"})
	addRule(&models.Rule{ID: "rule:aliyun:polardb-cluster-expired-check", Name: models.I18nString{"de": "PolarDB-Cluster Ablaufprüfung", "en": "PolarDB Cluster Expiration Check", "es": "Verificación de Expiración de Cluster PolarDB", "fr": "Vérification d'Expiration du Cluster PolarDB", "ja": "PolarDB クラスタの有効期限チェック", "pt": "Verificação de Expiração de Cluster PolarDB", "zh": "PolarDB 集群到期检查"}, Severity: "high", Description: models.I18nString{"de": "Vorausbezahlte PolarDB-Cluster sollten automatische Verlängerung aktiviert haben.", "en": "Prepaid PolarDB clusters should have auto-renewal enabled.", "es": "Los clústeres PolarDB prepagos deben tener renovación automática habilitada.", "fr": "Les clusters PolarDB prépayés doivent avoir le renouvellement automatique activé.", "ja": "プリペイド PolarDB クラスタは自動更新を有効にする必要があります。", "pt": "Clusters PolarDB pré-pagos devem ter renovação automática habilitada.", "zh": "预付费 PolarDB 集群应开启自动续费，避免业务中断。"}, Reason: models.I18nString{"de": "Der vorausbezahlte PolarDB-Cluster hat keine automatische Verlängerung aktiviert.", "en": "The prepaid PolarDB cluster does not have auto-renewal enabled.", "es": "El clúster PolarDB prepago no tiene renovación automática habilitada.", "fr": "Le cluster PolarDB prépayé n'a pas le renouvellement automatique activé.", "ja": "プリペイド PolarDB クラスタで自動更新が有効になっていません。", "pt": "O cluster PolarDB pré-pago não tem renovação automática habilitada.", "zh": "预付费 PolarDB 集群未开启自动续费。"}, Recommendation: models.I18nString{"de": "Aktivieren Sie die automatische Verlängerung für den vorausbezahlten PolarDB-Cluster, indem Sie RenewalStatus auf AutoRenewal setzen.", "en": "Enable auto-renewal for the prepaid PolarDB cluster by setting RenewalStatus to AutoRenewal.", "es": "Habilite la renovación automática para el clúster PolarDB prepago estableciendo RenewalStatus en AutoRenewal.", "fr": "Activez le renouvellement automatique pour le cluster PolarDB prépayé en définissant RenewalStatus sur AutoRenewal.", "ja": "RenewalStatus を AutoRenewal に設定して、プリペイド PolarDB クラスタで自動更新を有効にします。", "pt": "Habilite renovação automática para o cluster PolarDB pré-pago definindo RenewalStatus como AutoRenewal.", "zh": "通过将 RenewalStatus 设置为 AutoRenewal 为预付费 PolarDB 集群开启自动续费。"}, ResourceTypes: []string{"ALIYUN::POLARDB::DBCluster"}, IaCTypes: []string{"ros"}, Implementations: map[string]*models.RuleImpl(nil), FilePath: "aliyun/rules/ros/polardb-cluster-expired-check.rego", PackageName: "infraguard.rules.aliyun.polardb_cluster_expired_check", Content: "package infraguard.rules.aliyun.polardb_cluster_expired_check\n\nimport rego.v1\n\nimport data.infraguard.helpers\n\nrule_meta := {\n\t\"id\": \"polardb-cluster-expired-check\",\n\t\"severity\": \"high\",\n\t\"name\": {\n\t\t\"en\": \"PolarDB Cluster Expiration Check\",\n\t\t\"zh\": \"PolarDB 集群到期检查\",\n\t\t\"ja\": \"PolarDB クラスタの有効期限チェック\",\n\t\t\"de\": \"PolarDB-Cluster Ablaufprüfung\",\n\t\t\"es\": \"Verificación de Expiración de Cluster PolarDB\",\n\t\t\"fr\": \"Vérification d'Expiration du Cluster PolarDB\",\n\t\t\"pt\": \"Verificação de Expiração de Cluster PolarDB\"\n\t},\n\t\"description\": {\n\t\t\"en\": \"Prepaid PolarDB clusters should have auto-renewal enabled.\",\n\t\t\"zh\": \"预付费 PolarDB 集群应开启自动续费，避免业务中断。\",\n\t\t\"ja\": \"プリペイド PolarDB クラスタは自動更新を有効にする必要があります。\",\n\t\t\"de\": \"Vorausbezahlte PolarDB-Cluster sollten automatische Verlängerung aktiviert haben.\",\n\t\t\"es\": \"Los clústeres PolarDB prepagos deben tener renovación automática habilitada.\",\n\t\t\"fr\": \"Les clusters PolarDB prépayés doivent avoir le renouvellement automatique activé.\",\n\t\t\"pt\": \"Clusters PolarDB pré-pagos devem ter renovação automática habilitada.\"\n\t},\n\t\"reason\": {\n\t\t\"en\": \"The prepaid PolarDB cluster does not have auto-renewal enabled.\",\n\t\t\"zh\": \"预付费 PolarDB 集群未开启自动续费。\",\n\t\t\"ja\": \"プリペイド PolarDB クラスタで自動更新が有効になっていません。\",\n\t\t\"de\": \"Der vorausbezahlte PolarDB-Cluster hat keine automatische Verlängerung aktiviert.\",\n\t\t\"es\": \"El clúster PolarDB prepago no tiene renovación automática habilitada.\",\n\t\t\"fr\": \"Le cluster PolarDB prépayé n'a pas le renouvellement automatique activé.\",\n\t\t\"pt\": \"O cluster PolarDB pré-pago não tem renovação automática habilitada.\"\n\t},\n\t\"recommendation\": {\n\t\t\"en\": \"Enable auto-renewal for the prepaid PolarDB cluster by setting RenewalStatus to AutoRenewal.\",\n\t\t\"zh\": \"通过将 RenewalStatus 设置为 AutoRenewal 为预付费 PolarDB 集群开启自动续费。\",\n\t\t\"ja\": \"RenewalStatus を AutoRenewal に設定して、プリペイド PolarDB クラスタで自動更新を有効にします。\",\n\t\t\"de\": \"Aktivieren Sie die automatische Verlängerung für den vorausbezahlten PolarDB-Cluster, indem Sie RenewalStatus auf AutoRenewal setzen.\",\n\t\t\"es\": \"Habilite la renovación automática para el clúster PolarDB prepago estableciendo RenewalStatus en AutoRenewal.\",\n\t\t\"fr\": \"Activez le renouvellement automatique pour le cluster PolarDB prépayé en définissant RenewalStatus sur AutoRenewal.\",\n\t\t\"pt\": \"Habilite renovação automática para o cluster PolarDB pré-pago definindo RenewalStatus como AutoRenewal.\"\n\t},\n\t\"resource_types\": [\"ALIYUN::POLARDB::DBCluster\"]\n}\n\nis_prepaid(resource) if {\n\thelpers.get_property(resource, \"PayType\", \"Postpaid\") == \"Prepaid\"\n}\n\nis_auto_renew_enabled(resource) if {\n\tstatus := helpers.get_property(resource, \"RenewalStatus\", \"Normal\")\n\tstatus == \"AutoRenewal\"\n}\n\ndeny contains result if {\n\tsome name, resource in helpers.resources_by_types(rule_meta.resource_types)\n\tis_prepaid(resource)\n\tnot is_auto_renew_enabled(resource)\n\tresult := {\n\t\t\"id\": rule_meta.id,\n\t\t\"resource_id\": name,\n\t\t\"violation_path\": [\"Properties\", \"RenewalStatus\"],\n\t\t\"meta\": {\n\t\t\t\"severity\": rule_meta.severity,\n\t\t\t\"reason\": rule_meta.reason,\n\t\t\t\"recommendation\": rule_meta.recommendation,\n\t\t},\n\t}\n}\n"})
	addRule(&models.Rule{ID: "rule:aliyun:polardb-cluster-maintain-time-check", Name: models.I18nString{"de": "PolarDB-Cluster Wartungsfenster-Prüfung", "en": "PolarDB Cluster Maintenance Window Check", "es": "Verificación de Ventana de Mantenimiento de Cluster PolarDB", "fr": "Vérification de la Fenêtre de Maintenance du Cluster PolarDB", "ja": "PolarDB クラスタのメンテナンスウィンドウチェック", "pt": "Verificação de Janela de Manutenção de Cluster PolarDB", "zh": "PolarDB 集群维护时间检测"}, Severity: "low", Description: models.I18nString{"de": "Stellt sicher, dass der PolarDB-Cluster ein Wartungsfenster konfiguriert hat.", "en": "Ensures that the PolarDB cluster has a maintenance window configured.", "es": "Garantiza que el clúster PolarDB tenga una ventana de mantenimiento configurada.", "fr": "Garantit que le cluster PolarDB a une fenêtre de maintenance configurée.", "ja": "PolarDB クラスタにメンテナンスウィンドウが設定されていることを確認します。", "pt": "Garante que o cluster PolarDB tenha uma janela de manutenção configurada.", "zh": "确保 PolarDB 集群配置了维护时间段。"}, Reason: models.I18nString{"de": "Die Konfiguration eines Wartungsfensters ermöglicht geplante Wartung während der Nebenzeiten.", "en": "Configuring a maintenance window allows for planned maintenance during off-peak hours.", "es": "Configurar una ventana de mantenimiento permite realizar mantenimiento planificado durante las horas de menor actividad.", "fr": "Configurer une fenêtre de maintenance permet d'effectuer une maintenance planifiée pendant les heures creuses.", "ja": "メンテナンスウィンドウを設定することで、オフピーク時間帯に計画的なメンテナンスを行うことができます。", "pt": "Configurar uma janela de manutenção permite manutenção planejada durante horários de baixa demanda.", "zh": "配置维护时间段允许在非高峰时段进行计划内维护。"}, Recommendation: models.I18nString{"de": "Setzen Sie maintain_time für den PolarDB-Cluster.", "en": "Set maintain_time for the PolarDB cluster.", "es": "Establezca maintain_time para el clúster PolarDB.", "fr": "Définissez maintain_time pour le cluster PolarDB.", "ja": "PolarDB クラスタの maintain_time を設定します。", "pt": "Defina maintain_time para o cluster PolarDB.", "zh": "为 PolarDB 集群设置 maintain_time。"}, ResourceTypes: []string{"alicloud_polardb_cluster"}, IaCTypes: []string{"terraform"}, Implementations: map[string]*models.RuleImpl(nil), FilePath: "aliyun/rules/terraform/polardb-cluster-maintain-time-check.rego", PackageName: "infraguard.rules.terraform.polardb_cluster_maintain_time_check", Content: "package infraguard.rules.terraform.polardb_cluster_maintain_time_check\n\nimport rego.v1\n\nimport data.infraguard.helpers.terraform as tf\n\nrule_meta := {\n\t\"id\": \"polardb-cluster-maintain-time-check\",\n\t\"severity\": \"low\",\n\t\"name\": {\n\t\t\"en\": \"PolarDB Cluster Maintenance Window Check\",\n\t\t\"zh\": \"PolarDB 集群维护时间检测\",\n\t\t\"ja\": \"PolarDB クラスタのメンテナンスウィンドウチェック\",\n\t\t\"de\": \"PolarDB-Cluster Wartungsfenster-Prüfung\",\n\t\t\"es\": \"Verificación de Ventana de Mantenimiento de Cluster PolarDB\",\n\t\t\"fr\": \"Vérification de la Fenêtre de Maintenance du Cluster PolarDB\",\n\t\t\"pt\": \"Verificação de Janela de Manutenção de Cluster PolarDB\"\n\t},\n\t\"description\": {\n\t\t\"en\": \"Ensures that the PolarDB cluster has a maintenance window configured.\",\n\t\t\"zh\": \"确保 PolarDB 集群配置了维护时间段。\",\n\t\t\"ja\": \"PolarDB クラスタにメンテナンスウィンドウが設定されていることを確認します。\",\n\t\t\"de\": \"Stellt sicher, dass der PolarDB-Cluster ein Wartungsfenster konfiguriert hat.\",\n\t\t\"es\": \"Garantiza que el clúster PolarDB tenga una ventana de mantenimiento configurada.\",\n\t\t\"fr\": \"Garantit que le cluster PolarDB a une fenêtre de maintenance configurée.\",\n\t\t\"pt\": \"Garante que o cluster PolarDB tenha uma janela de manutenção configurada.\"\n\t},\n\t\"reason\": {\n\t\t\"en\": \"Configuring a maintenance window allows for planned maintenance during off-peak hours.\",\n\t\t\"zh\": \"配置维护时间段允许在非高峰时段进行计划内维护。\",\n\t\t\"ja\": \"メンテナンスウィンドウを設定することで、オフピーク時間帯に計画的なメンテナンスを行うことができます。\",\n\t\t\"de\": \"Die Konfiguration eines Wartungsfensters ermöglicht geplante Wartung während der Nebenzeiten.\",\n\t\t\"es\": \"Configurar una ventana de mantenimiento permite realizar mantenimiento planificado durante las horas de menor actividad.\",\n\t\t\"fr\": \"Configurer une fenêtre de maintenance permet d'effectuer une maintenance planifiée pendant les heures creuses.\",\n\t\t\"pt\": \"Configurar uma janela de manutenção permite manutenção planejada durante horários de baixa demanda.\"\n\t},\n\t\"recommendation\": {\n\t\t\"en\": \"Set maintain_time for the PolarDB cluster.\",\n\t\t\"zh\": \"为 PolarDB 集群设置 maintain_time。\",\n\t\t\"ja\": \"PolarDB クラスタの maintain_time を設定します。\",\n\t\t\"de\": \"Setzen Sie maintain_time für den PolarDB-Cluster.\",\n\t\t\"es\": \"Establezca maintain_time para el clúster PolarDB.\",\n\t\t\"fr\": \"Définissez maintain_time pour le cluster PolarDB.\",\n\t\t\"pt\": \"Defina maintain_time para o cluster PolarDB.\"\n\t},\n\t\"resource_types\": [\"alicloud_polardb_cluster\"],\n\t\"iac_type\": \"terraform\"\n}\n\ndeny contains violation if {\n\tsome name, resource in tf.resources_by_type(\"alicloud_polardb_cluster\")\n\tmaintain_time := tf.get_attribute(resource, \"maintain_time\", \"\")\n\tmaintain_time == \"\"\n\tviolation := {\n\t\t\"id\": rule_meta.id,\n\t\t\"resource_id\": sprintf(\"alicloud_polardb_cluster.%s\", [name]),\n\t\t\"meta\": {\"severity\": rule_meta.severity, \"reason\": rule_meta.reason, \"recommendation\": rule_meta.recommendation},\n\t}\n}\n"})
