	addPack(&models.Pack{ID: "pack:aliyun:cost-optimization", Name: models.I18nString{"de": "Kostenoptimierungspaket", "en": "Cost Optimization Pack", "es": "Paquete de optimización de costos", "fr": "Pack d'optimisation des coûts", "ja": "コスト最適化パック", "pt": "Pacote de otimização de custos", "zh": "成本优化合规包"}, Description: models.I18nString{"de": "Directory-Roll-up der Alibaba-Cloud-Kostenoptimierungs-Packs fuer Sizing, Idle-Ressourcen, Aufbewahrung, Speicher, Datenbanken, Cache, Netzwerk und Log-Kostenkontrollen.", "en": "Directory roll-up of Alibaba Cloud cost optimization packs for sizing, idle-resource detection, retention, storage, database, cache, network, and log cost controls.", "es": "Roll-up de directorio de packs de optimizacion de costos de Alibaba Cloud para dimensionamiento, recursos inactivos, retencion, almacenamiento, bases de datos, cache, red y logs.", "fr": "Roll-up de repertoire des packs d'optimisation des couts Alibaba Cloud pour dimensionnement, ressources inactives, retention, stockage, bases de donnees, cache, reseau et journaux.", "ja": "Alibaba Cloud のコスト最適化 pack をディレクトリ単位で集約し、サイズ選択、アイドルリソース検出、保持期間、ストレージ、データベース、キャッシュ、ネットワーク、ログのコスト制御を確認します。", "pt": "Roll-up de diretorio dos packs de otimizacao de custos do Alibaba Cloud para dimensionamento, recursos ociosos, retencao, armazenamento, bancos de dados, cache, rede e logs.", "zh": "阿里云成本优化目录级总包，汇总规格选型、闲置资源识别、保留周期、存储、数据库、缓存、网络和日志成本控制检查。"}, RuleIDs: []string{"rule:aliyun:ecs-disk-category-required", "rule:aliyun:ecs-disk-idle-check", "rule:aliyun:ecs-disk-size-required", "rule:aliyun:ecs-instance-bandwidth-configured", "rule:aliyun:ecs-instance-charge-type-required", "rule:aliyun:ecs-instance-type-required", "rule:aliyun:eip-bandwidth-required", "rule:aliyun:logstore-ttl-required", "rule:aliyun:nat-gateway-spec-required", "rule:aliyun:oss-storage-class-required", "rule:aliyun:rds-pay-type-required", "rule:aliyun:rds-storage-type-required", "rule:aliyun:redis-instance-class-required", "rule:aliyun:slb-internet-charge-type-required"}, FilePath: "aliyun/packs/cost-optimization/common-cost-optimization-pack.rego", PackageName: "infraguard.packs.aliyun.cost_optimization", Content: "package infraguard.packs.aliyun.cost_optimization\n\nimport rego.v1\n\npack_meta := {\n\t\"id\": \"cost-optimization\",\n\t\"name\": {\n\t\t\"en\": \"Cost Optimization Pack\",\n\t\t\"zh\": \"成本优化合规包\",\n\t\t\"ja\": \"コスト最適化パック\",\n\t\t\"de\": \"Kostenoptimierungspaket\",\n\t\t\"es\": \"Paquete de optimización de costos\",\n\t\t\"fr\": \"Pack d'optimisation des coûts\",\n\t\t\"pt\": \"Pacote de otimização de custos\"\n\t},\n\t\"description\": {\n\t\t\"en\": \"Directory roll-up of Alibaba Cloud cost optimization packs for sizing, idle-resource detection, retention, storage, database, cache, network, and log cost controls.\",\n\t\t\"zh\": \"阿里云成本优化目录级总包，汇总规格选型、闲置资源识别、保留周期、存储、数据库、缓存、网络和日志成本控制检查。\",\n\t\t\"ja\": \"Alibaba Cloud のコスト最適化 pack をディレクトリ単位で集約し、サイズ選択、アイドルリソース検出、保持期間、ストレージ、データベース、キャッシュ、ネットワーク、ログのコスト制御を確認します。\",\n\t\t\"de\": \"Directory-Roll-up der Alibaba-Cloud-Kostenoptimierungs-Packs fuer Sizing, Idle-Ressourcen, Aufbewahrung, Speicher, Datenbanken, Cache, Netzwerk und Log-Kostenkontrollen.\",\n\t\t\"es\": \"Roll-up de directorio de packs de optimizacion de costos de Alibaba Cloud para dimensionamiento, recursos inactivos, retencion, almacenamiento, bases de datos, cache, red y logs.\",\n\t\t\"fr\": \"Roll-up de repertoire des packs d'optimisation des couts Alibaba Cloud pour dimensionnement, ressources inactives, retention, stockage, bases de donnees, cache, reseau et journaux.\",\n\t\t\"pt\": \"Roll-up de diretorio dos packs de otimizacao de custos do Alibaba Cloud para dimensionamento, recursos ociosos, retencao, armazenamento, bancos de dados, cache, rede e logs.\"\n\t},\n\t\"rules\": [\n\t\t\"ecs-disk-category-required\",\n\t\t\"ecs-disk-idle-check\",\n\t\t\"ecs-disk-size-required\",\n\t\t\"ecs-instance-bandwidth-configured\",\n\t\t\"ecs-instance-charge-type-required\",\n\t\t\"ecs-instance-type-required\",\n\t\t\"eip-bandwidth-required\",\n\t\t\"logstore-ttl-required\",\n\t\t\"nat-gateway-spec-required\",\n\t\t\"oss-storage-class-required\",\n\t\t\"rds-pay-type-required\",\n\t\t\"rds-storage-type-required\",\n\t\t\"redis-instance-class-required\",\n\t\t\"slb-internet-charge-type-required\"\n\t]\n}\n"})
